const n = Math.max(1, Math.min(4, Math.floor(params.seats)));
const span = 1.25 + n * 0.72;
const height = 2.35;
const endInset = 0.18;
const frameX = span / 2 - endInset;
const footSpread = 0.78;
const postR = 0.055;
const frameMat = { preset: 'metal', color: params.color, metalness: 0.65, roughness: 0.32 };
const darkMetal = { preset: 'metal', color: '#303841', metalness: 0.78, roughness: 0.28 };
const chainMat = { preset: 'metal', color: '#9ba5ad', metalness: 0.9, roughness: 0.22 };
const seatMat = { preset: 'rubber', color: '#26343c', roughness: 0.72 };
const capMat = { preset: 'plastic', color: '#f2b632', roughness: 0.42 };
for (let side = -1; side <= 1; side += 2) {
  const x = side * frameX;
  api.add(api.tube([[x, 0.06, -footSpread], [x, height, 0]], postR, 10), frameMat);
  api.add(api.tube([[x, 0.06, footSpread], [x, height, 0]], postR, 10), frameMat);
  api.add(api.tube([[x, 0.72, -footSpread * 0.7], [x, 0.72, footSpread * 0.7]], postR * 0.72, 8), frameMat);
  api.add(api.cylinder(postR * 1.45, postR * 1.45, 0.16, 12).rotate(0, 0, 90).translate(x, height, 0), darkMetal);
  for (let zSide = -1; zSide <= 1; zSide += 2) {
    api.add(api.cylinder(postR * 1.35, postR * 1.55, 0.07, 10).translate(x, 0.035, zSide * footSpread), darkMetal);
  }
}
api.add(api.cylinder(postR * 1.2, postR * 1.2, span + 0.3, 12).rotate(0, 0, 90).translate(0, height, 0), frameMat);
api.add(api.cylinder(postR * 1.5, postR * 1.5, 0.08, 12).rotate(0, 0, 90).translate(-span / 2 - 0.15, height, 0), capMat);
api.add(api.cylinder(postR * 1.5, postR * 1.5, 0.08, 12).rotate(0, 0, 90).translate(span / 2 + 0.15, height, 0), capMat);
const usable = span - 0.62;
const spacing = usable / n;
for (let i = 0; i < n; i++) {
  const sx = -usable / 2 + spacing * (i + 0.5);
  const chainGap = Math.min(0.32, spacing * 0.42);
  const hangerY = height - 0.09;
  const seatY = 0.62;
  const seatW = chainGap + 0.2;
  for (let side = -1; side <= 1; side += 2) {
    const cx = sx + side * chainGap / 2;
    api.add(api.torus(0.065, 0.014).rotate(0, 90, 0).translate(cx, hangerY, 0), darkMetal);
    api.add(api.tube([[cx, hangerY - 0.05, 0], [cx, seatY + 0.09, -0.12]], 0.012, 6), chainMat);
    api.add(api.tube([[cx, hangerY - 0.05, 0], [cx, seatY + 0.09, 0.12]], 0.012, 6), chainMat);
    api.add(api.cylinder(0.025, 0.025, 0.08, 8).translate(cx, seatY + 0.06, 0), darkMetal);
  }
  const seat = api.box(seatW, 0.075, 0.38).translate(sx, seatY, 0);
  api.add(seat, seatMat);
  api.add(api.box(seatW * 0.9, 0.018, 0.28).translate(sx, seatY + 0.047, 0), { preset: 'rubber', color: '#3f535d', roughness: 0.68 });
  api.add(api.box(0.035, 0.09, 0.32).translate(sx - seatW * 0.42, seatY, 0), darkMetal);
  api.add(api.box(0.035, 0.09, 0.32).translate(sx + seatW * 0.42, seatY, 0), darkMetal);
}
api.add(api.box(span - 0.45, 0.035, 0.045).translate(0, height - 0.18, -0.03), darkMetal);
api.autoColliders('hull');
return api.build();
